package io.screentrace.adapter.spring;
import com.github.javaparser.ast.*;import com.github.javaparser.ast.body.*;import com.github.javaparser.ast.expr.*;import com.github.javaparser.ast.stmt.*;import com.fasterxml.jackson.databind.ObjectMapper;import io.screentrace.core.ApplicationGraph;import io.screentrace.core.ApplicationGraph.*;import io.screentrace.parser.jsp.JavaSources;import io.screentrace.scanner.ProjectScanner.ProjectInventory;import io.screentrace.scanner.SafeProjectFiles;import java.util.*;
/** Direct DTO scalar copies into a source-proven JPA entity. Session-local submitted fields only. */
final class SpringDtoSimulation {
 private record Type(ClassOrInterfaceDeclaration node,String file){}
 private record Operation(Type repository,Type entity,Type dto,String kind,Map<String,String> fields,boolean update,List<SourceLocation> proof){}
 private final Map<String,List<Type>> types=new TreeMap<>();private final ObjectMapper json=new ObjectMapper();
 private Type unique(String name){if(name==null)return null;var matches=types.getOrDefault(name,List.of());return matches.size()==1?matches.get(0):null;}
 static ApplicationGraph enrich(ApplicationGraph graph,ProjectInventory inventory){return new SpringDtoSimulation().analyze(graph,inventory);}
 private ApplicationGraph analyze(ApplicationGraph graph,ProjectInventory inventory){
  for(var file:inventory.javaFiles())try{var unit=JavaSources.parse(SafeProjectFiles.readUtf8Limited(inventory.root(),file,SafeProjectFiles.MAX_SOURCE_FILE_BYTES));String path=inventory.root().relativize(file).toString().replace('\\','/');for(var declaration:unit.getTypes())if(declaration instanceof ClassOrInterfaceDeclaration c)types.computeIfAbsent(c.getNameAsString(),k->new ArrayList<>()).add(new Type(c,path));}catch(Exception ignored){}
  Map<String,Operation> operations=new TreeMap<>();
  for(var entries:types.values())if(entries.size()==1){var type=entries.get(0);if(type.node.isInterface())continue;for(var method:type.node.getMethods()){var operation=writeOperation(type,method);if(operation!=null&&type.node.getMethodsByName(method.getNameAsString()).size()==1)operations.put(type.file+":"+method.getNameAsString(),operation);}}
  Map<String,List<String>> collections=new TreeMap<>();for(var op:operations.values())collections.computeIfAbsent(key(op),k->new ArrayList<>()).addAll(op.fields.keySet());
  Map<String,List<Map<String,Object>>> reads=new TreeMap<>();Map<String,List<AnalysisEvidence>> readProof=new TreeMap<>();List<GraphNode> changed=new ArrayList<>();
  for(var handler:graph.nodes()){
   if(handler.type()!=NodeType.HANDLER||handler.attributes().containsKey("simulationData")){changed.add(handler);continue;}var owner=unique(handler.attributes().get("class"));if(owner==null||!owner.file.equals(handler.source().file())){changed.add(handler);continue;}var methods=owner.node.getMethodsByName(handler.attributes().getOrDefault("method",""));if(methods.size()!=1){changed.add(handler);continue;}var method=methods.get(0);List<Map<String,Object>> contracts=new ArrayList<>();List<AnalysisEvidence> proof=new ArrayList<>(handler.evidence());
   for(var call:method.findAll(MethodCallExpr.class)){var service=receiver(owner,call);if(service==null)continue;var implementations=implementation(service);if(implementations==null)continue;var called=implementations.node.getMethodsByName(call.getNameAsString()).stream().filter(m->m.getParameters().size()==call.getArguments().size()).toList();if(called.size()!=1)continue;var serviceMethod=called.get(0);var write=operations.get(implementations.file+":"+serviceMethod.getNameAsString());Operation op=write;
    if(op==null)op=readOperation(implementations,serviceMethod,collections);if(op==null)continue;final Operation action=op;String collection=key(op);List<String> fields=collections.getOrDefault(collection,List.of()).stream().distinct().sorted().toList();String id=id(op.entity);if(id==null||fields.isEmpty()||fields.size()>63)continue;fields=new ArrayList<>(fields);if(!fields.contains(id))fields.add(id);fields=fields.stream().sorted().toList();Map<String,Object> contract=new TreeMap<>();contract.put("version",1);contract.put("operation",op.kind);contract.put("collection",collection);contract.put("fields",fields);contract.put("idField",id);contract.put("scope","submitted-fields-only");
    if(op.kind.equals("upsert")){
     if(call.getArguments().size()!=1||!call.getArgument(0).isNameExpr())continue;String arg=call.getArgument(0).asNameExpr().getNameAsString();var parameters=method.getParameters().stream().filter(p->p.getNameAsString().equals(arg)&&p.getAnnotationByName("ModelAttribute").isPresent()&&unique(p.getType().asString())==action.dto).toList();if(parameters.size()!=1||method.findAll(AssignExpr.class).stream().anyMatch(a->a.getTarget().toString().equals(arg)))continue;
     boolean rewritten=method.findAll(MethodCallExpr.class).stream().anyMatch(c->c.getScope().filter(s->s.toString().equals(arg)).isPresent()&&opFieldsSetter(action.fields,c));if(rewritten||op.update&&!updateIdentity(method,serviceMethod,call,arg,op.dto))continue;contract.put("inputFields",op.fields);if(op.update)contract.put("useSelectedIdentity",true);else contract.put("generatedIdentity",true);
    }else if(op.kind.startsWith("read")){
     Set<String> models=new TreeSet<>();for(var binding:method.findAll(MethodCallExpr.class))if(binding.getNameAsString().equals("addAttribute")&&binding.getArguments().size()==2&&binding.getArgument(0).isStringLiteralExpr()){
      Expression value=binding.getArgument(1);if(value.isNameExpr()){String variable=value.asNameExpr().getNameAsString();var declarations=method.findAll(VariableDeclarator.class).stream().filter(v->v.getNameAsString().equals(variable)&&v.getInitializer().isPresent()).toList();if(declarations.size()==1)value=declarations.get(0).getInitializer().get();}
      if(value==call||op.kind.equals("readOne")&&projection(method,call,binding.getArgument(1),op.entity,fields))models.add(binding.getArgument(0).asStringLiteralExpr().asString());
     }if(models.size()!=1||method.findAll(MethodCallExpr.class).stream().anyMatch(c->action.kind.equals("readAll")&&action.entity.node.getMethodsByName(c.getNameAsString()).stream().anyMatch(m->fieldsCopy(action,collections).contains(setterProperty(action.entity,c)))))continue;contract.put("model",models.iterator().next());
    }
    contracts.add(contract);for(var source:op.proof)proof.add(new AnalysisEvidence(source,"SpringDtoSimulation",ResolutionStatus.INFERRED,"可證明的 scalar DTO 複製／repository 路徑；只回放本機提交欄位，不執行 SQL、session、關聯、分類或日期計算"));proof.add(new AnalysisEvidence(new SourceLocation(owner.file,call.getBegin().orElseThrow().line),"SpringDtoSimulation",ResolutionStatus.INFERRED,"來源 handler 及服務呼叫；operation="+op.kind));
   }
   contracts=new ArrayList<>(new LinkedHashSet<>(contracts));if(contracts.isEmpty()){changed.add(handler);continue;}var attrs=new TreeMap<>(handler.attributes());try{if(contracts.size()==1)attrs.put("simulationData",json.writeValueAsString(contracts.get(0)));}catch(Exception ignored){}reads.put(handler.id(),contracts.stream().filter(c->c.get("operation").toString().startsWith("read")).toList());readProof.put(handler.id(),proof.stream().filter(e->e.parser().equals("SpringDtoSimulation")).toList());changed.add(new GraphNode(handler.id(),handler.type(),handler.name(),attrs,handler.source(),handler.confidence(),proof));
  }
  List<GraphNode> nodes=new ArrayList<>();for(var screen:changed){if(screen.type()!=NodeType.SCREEN){nodes.add(screen);continue;}List<Map<String,Object>> bindings=new ArrayList<>();List<AnalysisEvidence> proof=new ArrayList<>(screen.evidence());for(var edge:graph.relationships())if(edge.type()==EdgeType.RENDERS&&edge.to().equals(screen.id())){bindings.addAll(reads.getOrDefault(edge.from(),List.of()));proof.addAll(readProof.getOrDefault(edge.from(),List.of()));}if(bindings.isEmpty()){nodes.add(screen);continue;}var attrs=new TreeMap<>(screen.attributes());try{attrs.put("simulationBindings",json.writeValueAsString(bindings.stream().distinct().toList()));}catch(Exception ignored){}nodes.add(new GraphNode(screen.id(),screen.type(),screen.name(),attrs,screen.source(),screen.confidence(),proof));}
  return new ApplicationGraph(graph.application(),nodes,graph.relationships(),graph.diagnostics(),graph.apiContracts(),graph.schemaVersion(),graph.behaviors(),graph.validationRules());
 }
 private static Set<String> fieldsCopy(Operation action,Map<String,List<String>> collections){return new HashSet<>(collections.getOrDefault(key(action),List.of()));}
 private static boolean injected(Type owner,VariableDeclarator field){
  var declaration=field.findAncestor(FieldDeclaration.class).orElseThrow();if(field.getInitializer().isPresent())return false;
  if(declaration.getAnnotationByName("Autowired").isPresent())return true;
  var constructors=owner.node.getConstructors();if(constructors.size()!=1)return false;var constructor=constructors.get(0);
  return constructor.getParameters().stream().filter(p->p.getType().asString().equals(field.getType().asString())).anyMatch(p->constructor.getBody().getStatements().stream().anyMatch(st->st.isExpressionStmt()&&st.asExpressionStmt().getExpression().isAssignExpr()&&st.asExpressionStmt().getExpression().asAssignExpr().getOperator()==AssignExpr.Operator.ASSIGN&&st.asExpressionStmt().getExpression().asAssignExpr().getTarget().toString().equals("this."+field.getNameAsString())&&st.asExpressionStmt().getExpression().asAssignExpr().getValue().toString().equals(p.getNameAsString())));
 }
 private static boolean updateIdentity(MethodDeclaration controller,MethodDeclaration service,MethodCallExpr invocation,String dtoName,Type dto){
  var finds=service.findAll(MethodCallExpr.class).stream().filter(c->c.getNameAsString().equals("findById")&&c.getArguments().size()==1&&c.getArgument(0).isMethodCallExpr()).toList();if(finds.size()!=1)return false;
  String property=getterProperty(dto,finds.get(0).getArgument(0).asMethodCallExpr(),service.getParameter(0).getNameAsString());if(property==null)return false;
  var setters=controller.findAll(MethodCallExpr.class).stream().filter(c->c.getScope().filter(v->v.toString().equals(dtoName)).isPresent()&&property.equals(setterProperty(dto,c))).toList();if(setters.size()!=1)return false;var setter=setters.get(0);if(!setter.getArgument(0).isNameExpr()||setter.getEnd().orElseThrow().isAfter(invocation.getBegin().orElseThrow()))return false;
  String parameter=setter.getArgument(0).asNameExpr().getNameAsString();return controller.getParameters().stream().anyMatch(p->p.getNameAsString().equals(parameter)&&p.getAnnotationByName("RequestParam").isPresent());
 }
 private boolean projection(MethodDeclaration method,MethodCallExpr source,Expression target,Type entity,List<String> fields){
  if(!target.isNameExpr())return false;String name=target.asNameExpr().getNameAsString();var vars=method.findAll(VariableDeclarator.class);var sources=vars.stream().filter(v->v.getInitializer().orElse(null)==source).toList();var destinations=vars.stream().filter(v->v.getNameAsString().equals(name)&&v.getInitializer().filter(Expression::isObjectCreationExpr).isPresent()).toList();if(sources.size()!=1||destinations.size()!=1)return false;Type dto=unique(destinations.get(0).getType().asString());if(dto==null)return false;Set<String> proved=new TreeSet<>();
  for(var call:method.findAll(MethodCallExpr.class))if(call.getScope().filter(v->v.toString().equals(name)).isPresent()){
   String field=setterProperty(dto,call);if(field==null)return false;if(!fields.contains(field)||field.equals(id(entity)))continue;
   if(!call.getArgument(0).isMethodCallExpr()||!field.equals(getterProperty(entity,call.getArgument(0).asMethodCallExpr(),sources.get(0).getNameAsString()))||!proved.add(field))return false;
  }return fields.stream().filter(f->!f.equals(id(entity))).allMatch(proved::contains);
 }
 private static boolean opFieldsSetter(Map<String,String> fields,MethodCallExpr call){return fields.values().stream().anyMatch(p->call.getNameAsString().equals("set"+upper(p)));}
 private Type implementation(Type type){if(!type.node.isInterface())return type;var candidates=types.values().stream().filter(v->v.size()==1).map(v->v.get(0)).filter(t->t.node.getImplementedTypes().stream().anyMatch(i->i.getNameAsString().equals(type.node.getNameAsString()))&&t.node.getAnnotationByName("Service").isPresent()).toList();return candidates.size()==1?candidates.get(0):null;}
 private Type receiver(Type owner,MethodCallExpr call){if(call.getScope().filter(Expression::isNameExpr).isEmpty())return null;String name=call.getScope().get().asNameExpr().getNameAsString();var method=call.findAncestor(MethodDeclaration.class);if(method.isPresent()&&(method.get().getParameters().stream().anyMatch(p->p.getNameAsString().equals(name))||method.get().findAll(VariableDeclarator.class).stream().anyMatch(v->v.getNameAsString().equals(name))))return null;var fields=owner.node.getFields().stream().filter(f->!f.isStatic()).flatMap(f->f.getVariables().stream()).filter(v->v.getNameAsString().equals(name)).toList();return fields.size()==1&&injected(owner,fields.get(0))?unique(fields.get(0).getType().asString()):null;}
 private Operation writeOperation(Type owner,MethodDeclaration method){
  if(method.getBody().isEmpty()||method.getParameters().size()!=1||!method.getBody().get().getStatements().stream().allMatch(s->s.isExpressionStmt()||s.isReturnStmt()))return null;String dtoName=method.getParameter(0).getNameAsString();Type dto=unique(method.getParameter(0).getType().asString());if(dto==null)return null;
  var saves=method.findAll(MethodCallExpr.class).stream().filter(c->c.getNameAsString().equals("save")&&c.getArguments().size()==1&&c.getArgument(0).isNameExpr()&&repository(receiver(owner,c))!=null).toList();if(saves.size()!=1||!receiver(owner,saves.get(0)).node.getMethodsByName("save").isEmpty())return null;var save=saves.get(0);Type repo=receiver(owner,save),entity=repository(repo);if(entity==null||entity.equals(dto)||id(entity)==null)return null;String variable=save.getArgument(0).asNameExpr().getNameAsString();var definitions=method.findAll(VariableDeclarator.class).stream().filter(v->v.getNameAsString().equals(variable)&&v.getInitializer().isPresent()).toList();if(definitions.size()!=1)return null;Expression init=definitions.get(0).getInitializer().get();boolean update=false;
  if(init.isObjectCreationExpr()){if(!init.asObjectCreationExpr().getType().asString().equals(entity.node.getNameAsString())||!init.asObjectCreationExpr().getArguments().isEmpty())return null;}else if(init.isMethodCallExpr()&&init.asMethodCallExpr().getNameAsString().equals("orElse")&&init.asMethodCallExpr().getArguments().size()==1&&init.asMethodCallExpr().getArgument(0).isNullLiteralExpr()&&init.asMethodCallExpr().getScope().filter(Expression::isMethodCallExpr).isPresent()){var find=init.asMethodCallExpr().getScope().get().asMethodCallExpr();if(!find.getNameAsString().equals("findById")||receiver(owner,find)!=repo||find.getArguments().size()!=1||!find.getArgument(0).isMethodCallExpr()||getterProperty(dto,find.getArgument(0).asMethodCallExpr(),dtoName)==null)return null;update=true;}else return null;
  Map<String,String> fields=new TreeMap<>();List<SourceLocation> proof=new ArrayList<>();for(var call:method.findAll(MethodCallExpr.class))if(call.getScope().filter(s->s.toString().equals(variable)).isPresent()){
   String property=setterProperty(entity,call);if(property==null)return null;if(scalar(entity,property)&&(!call.getArgument(0).isMethodCallExpr()||getterProperty(dto,call.getArgument(0).asMethodCallExpr(),dtoName)==null))return null;if(call.getArguments().size()==1&&call.getArgument(0).isMethodCallExpr()){String input=getterProperty(dto,call.getArgument(0).asMethodCallExpr(),dtoName);if(input!=null&&scalar(entity,property)&&scalar(dto,input)){if(fields.putIfAbsent(property,input)!=null)return null;proof.add(new SourceLocation(owner.file,call.getBegin().orElseThrow().line));}}
  }
  if(fields.isEmpty()||fields.containsKey(id(entity))||!method.findAll(AssignExpr.class).isEmpty())return null;
  if(!update&&entity.node.getFields().stream().noneMatch(f->f.getAnnotationByName("Id").isPresent()&&f.getAnnotationByName("GeneratedValue").isPresent()))return null;
  for(var n:method.findAll(NameExpr.class))if(n.getNameAsString().equals(variable)){Node parent=n.getParentNode().orElse(null);if(parent instanceof MethodCallExpr c&&c.getScope().orElse(null)==n&&setterProperty(entity,c)!=null)continue;if(parent==save&&save.getArgument(0)==n)continue;return null;}
  for(var n:method.findAll(NameExpr.class))if(n.getNameAsString().equals(dtoName)){Node parent=n.getParentNode().orElse(null);if(parent instanceof MethodCallExpr c&&c.getScope().orElse(null)==n&&getterProperty(dto,c,dtoName)!=null)continue;if(parent instanceof MethodCallExpr c&&c.getNameAsString().equals("println")&&c.getScope().map(Object::toString).orElse("").equals("System.out")&&unique("System")==null&&pureToString(dto))continue;return null;}
proof.add(new SourceLocation(repo.file,repo.node.getBegin().orElseThrow().line));proof.add(new SourceLocation(entity.file,entity.node.getBegin().orElseThrow().line));return new Operation(repo,entity,dto,"upsert",fields,update,proof);
 }
 private Operation readOperation(Type owner,MethodDeclaration method,Map<String,List<String>> collections){if(method.getBody().isEmpty()||method.getBody().get().getStatements().size()!=1||!(method.getBody().get().getStatement(0).isReturnStmt()||method.getBody().get().getStatement(0).isExpressionStmt()))return null;var statement=method.getBody().get().getStatement(0);Expression expression=statement.isReturnStmt()?statement.asReturnStmt().getExpression().orElse(null):statement.asExpressionStmt().getExpression();if(expression instanceof MethodCallExpr unwrap&&unwrap.getNameAsString().equals("orElse")&&unwrap.getScope().isPresent())expression=unwrap.getScope().get();if(!(expression instanceof MethodCallExpr call))return null;Type repo=receiver(owner,call),entity=repository(repo);if(entity==null)return null;if(!call.getNameAsString().startsWith("findBy")&&!repo.node.getMethodsByName(call.getNameAsString()).isEmpty())return null;String kind=switch(call.getNameAsString()){case "findById"->"readOne";case "deleteById"->"delete";case "findAll"->"readAll";default->derivedCollection(repo,entity,call)?"readAll":null;};if(kind==null||!collections.containsKey(repo.file+":"+repo.node.getNameAsString()))return null;return new Operation(repo,entity,null,kind,Map.of(),false,List.of(new SourceLocation(owner.file,call.getBegin().orElseThrow().line),new SourceLocation(repo.file,repo.node.getBegin().orElseThrow().line)));}
 private Type repository(Type type){if(type==null||!type.node.isInterface())return null;var bases=type.node.getExtendedTypes().stream().filter(t->t.getNameAsString().equals("JpaRepository")&&t.getTypeArguments().isPresent()&&t.getTypeArguments().get().size()==2).toList();if(bases.size()!=1||type.node.findCompilationUnit().orElseThrow().getImports().stream().noneMatch(i->i.getNameAsString().equals("org.springframework.data.jpa.repository.JpaRepository")))return null;return unique(bases.get(0).getTypeArguments().get().get(0).asString());}
 private boolean derivedCollection(Type repo,Type entity,MethodCallExpr call){String name=call.getNameAsString();if(!name.startsWith("findBy")||call.getArguments().size()!=1)return false;var methods=repo.node.getMethodsByName(name);if(methods.size()!=1||methods.get(0).getBody().isPresent()||methods.get(0).getAnnotationByName("Query").isPresent()||!methods.get(0).getType().asString().equals("List<"+entity.node.getNameAsString()+">"))return false;String key=name.substring(6);for(var field:entity.node.getFields())for(var v:field.getVariables()){if(key.equals(upper(v.getNameAsString())))return true;Type nested=unique(v.getType().asString());if(nested!=null){String id=id(nested);if(id!=null&&key.equals(upper(v.getNameAsString())+upper(id)))return true;}}return false;}
 private String id(Type type){var ids=type.node.getFields().stream().filter(f->f.getAnnotationByName("Id").isPresent()).flatMap(f->f.getVariables().stream()).map(v->v.getNameAsString()).toList();return ids.size()==1&&scalar(type,ids.get(0))?ids.get(0):null;}
 private static String key(Operation op){return op.repository.file+":"+op.repository.node.getNameAsString();}
 private static String upper(String s){return Character.toUpperCase(s.charAt(0))+s.substring(1);}
 private static boolean scalar(Type type,String name){return type.node.getFields().stream().filter(f->!f.isStatic()).flatMap(f->f.getVariables().stream()).anyMatch(v->v.getNameAsString().equals(name)&&Set.of("String","int","Integer","long","Long","double","Double","boolean","Boolean").contains(v.getType().asString()));}
 private static String getterProperty(Type type,MethodCallExpr call,String receiver){if(!call.getArguments().isEmpty()||call.getScope().filter(s->s.toString().equals(receiver)).isEmpty())return null;var methods=type.node.getMethodsByName(call.getNameAsString());if(methods.size()!=1)return null;var m=methods.get(0);if(!m.isPublic()||m.isStatic()||!m.getParameters().isEmpty()||m.getBody().isEmpty()||m.getBody().get().getStatements().size()!=1||!m.getBody().get().getStatement(0).isReturnStmt())return null;String field=m.getBody().get().getStatement(0).asReturnStmt().getExpression().map(Object::toString).orElse("").replaceFirst("^this\\.","");return scalar(type,field)?field:null;}
 private static boolean pureToString(Type type){var methods=type.node.getMethodsByName("toString");return methods.size()==1&&methods.get(0).findAll(MethodCallExpr.class).isEmpty()&&methods.get(0).findAll(AssignExpr.class).isEmpty()&&methods.get(0).findAll(UnaryExpr.class).isEmpty();}
 private static String setterProperty(Type type,MethodCallExpr call){if(!call.getNameAsString().startsWith("set")||call.getNameAsString().length()<4||call.getArguments().size()!=1)return null;var methods=type.node.getMethodsByName(call.getNameAsString());if(methods.size()!=1)return null;var m=methods.get(0);if(!m.isPublic()||m.isStatic()||m.getParameters().size()!=1||m.getBody().isEmpty()||m.getBody().get().getStatements().size()!=1||!m.getBody().get().getStatement(0).isExpressionStmt())return null;var expression=m.getBody().get().getStatement(0).asExpressionStmt().getExpression();if(!(expression instanceof AssignExpr a)||a.getOperator()!=AssignExpr.Operator.ASSIGN||!a.getValue().toString().equals(m.getParameter(0).getNameAsString())||!a.getTarget().toString().equals("this."+call.getNameAsString().substring(3,4).toLowerCase(Locale.ROOT)+call.getNameAsString().substring(4))||!call.getNameAsString().startsWith("set")||call.getNameAsString().length()<4)return null;return a.getTarget().toString().substring(5);}
}
